const entrada = $input.first().json || {};
const texto = v => String(v ?? '').trim();
const primero = (...valores) => valores.map(texto).find(Boolean) || '';
if (Object.prototype.hasOwnProperty.call(entrada, 'pago_confirmado')) {
  return [{json:{...entrada,
    email_pago: texto(entrada.email_pago).toLowerCase(),
    nombre_pago: texto(entrada.nombre_pago),
    reserva_draft_id_metadata: texto(entrada.reserva_draft_id_metadata),
    referencia_cliente: texto(entrada.referencia_cliente),
    subscriber_id_metadata: texto(entrada.subscriber_id_metadata),
    pago_confirmado: entrada.pago_confirmado === true || entrada.pago_confirmado === 'true',
  }}];
}
const evento = entrada.body && typeof entrada.body === 'object' ? entrada.body : entrada;
const sesion = evento.data?.object ?? (typeof evento.object === 'object' ? evento.object : evento);
const metadata = sesion.metadata || {};
const tipo = texto(evento.type) || (sesion.object === 'checkout.session' && sesion.status === 'complete' ? 'checkout.session.completed' : '');
const estado = texto(sesion.payment_status).toLowerCase();
if (estado === 'paid') {
  if (!/^cs_(?:live|test)_/.test(texto(sesion.id))) throw new Error('Stripe no entregÃ³ una sesiÃ³n identificable.');
  if (!Number.isSafeInteger(sesion.amount_total) || sesion.amount_total <= 0) throw new Error('Stripe no entregÃ³ un importe vÃ¡lido en centavos.');
  if (!/^[a-z]{3}$/.test(texto(sesion.currency).toLowerCase())) throw new Error('Stripe no entregÃ³ una moneda vÃ¡lida.');
}
const draftMetadata = primero(metadata.reserva_draft_id, metadata.draft_id);
const referencia = texto(sesion.client_reference_id);
if (draftMetadata && referencia && draftMetadata !== referencia) throw new Error('Stripe contiene dos IDs de reserva diferentes; revisar la asociaciÃ³n.');
const draftId = primero(draftMetadata, referencia);
if (draftId && !/^[1-9]\d*$/.test(draftId)) throw new Error('El ID de borrador recibido de Stripe no es vÃ¡lido.');
return [{json:{
  livemode: (sesion.livemode ?? evento.livemode) === true,
  evento_stripe_id: texto(evento.id).startsWith('evt_') ? texto(evento.id) : '',
  stripe_checkout_session_id: texto(sesion.id),
  stripe_payment_intent_id: texto(sesion.payment_intent?.id ?? sesion.payment_intent),
  stripe_payment_link_id: texto(sesion.payment_link),
  tipo_evento_stripe: tipo,
  estado_pago_stripe: estado,
  pago_confirmado: ['checkout.session.completed','checkout.session.async_payment_succeeded'].includes(tipo) && estado === 'paid',
  email_pago: primero(sesion.customer_details?.email,sesion.customer_email,metadata.email_cliente,metadata.email).toLowerCase(),
  nombre_pago: primero(sesion.customer_details?.name,metadata.nombre_cliente),
  subscriber_id_metadata: texto(metadata.subscriber_id),
  reserva_draft_id_metadata: draftId,
  referencia_cliente: referencia,
  monto_total: sesion.amount_total ?? null,
  moneda: texto(sesion.currency).toLowerCase(),
  fecha_evento_stripe: Number(evento.created) > 0 ? new Date(Number(evento.created)*1000).toISOString() : null,
}}];

const pago = $('Analizar pago Stripe1').first().json;
const filas = $input.all()
  .map(item => item.json)
  .filter(item => item && Object.keys(item).length);

const intento = $runIndex + 1;
const subscriberMetadata = String(pago.subscriber_id_metadata ?? '').trim();
const draftMetadata = String(pago.reserva_draft_id_metadata ?? '').trim();
const stripeSessionId = String(pago.stripe_checkout_session_id ?? '').trim();

function lista(valor) {
  if (valor === undefined || valor === null || valor === '') return [];
  if (Array.isArray(valor)) return valor.flatMap(lista);
  if (typeof valor === 'string') {
    const texto = valor.trim();
    if (!texto) return [];
    try {
      const convertido = JSON.parse(texto);
      if (Array.isArray(convertido)) return convertido.flatMap(lista);
    } catch {}
    return texto.split(/\s*(?:,|\+|;|\|)\s*/).filter(Boolean);
  }
  return [valor];
}

function idDe(valor) {
  if (valor && typeof valor === 'object') {
    return valor.id ?? valor.employee_id ?? valor.terapeuta_id ?? valor.recurso_id ?? null;
  }
  return valor;
}

function idsUnicos(valores) {
  return [...new Set(
    valores
      .map(idDe)
      .filter(valor => valor !== null && valor !== undefined && valor !== '')
      .map(valor => String(valor).trim())
      .filter(Boolean)
  )];
}

function booleano(valor, porDefecto = false) {
  if (valor === undefined || valor === null || valor === '') return porDefecto;
  if (typeof valor === 'boolean') return valor;
  return ['1', 'true', 'si', 'sÃ­', 'yes'].includes(String(valor).trim().toLowerCase());
}

function enteroPositivo(valor) {
  const numero = Number(valor);
  return Number.isInteger(numero) && numero > 0 ? numero : null;
}

const emailPago = String(pago.email_pago ?? '').trim().toLowerCase();
const candidatasUnicas = [...new Map(filas.filter(f=>f.id).map(f=>[String(f.id), f])).values()];
const vinculadasAStripe = candidatasUnicas.filter(f=>stripeSessionId && String(f.stripe_checkout_session_id ?? '').trim() === stripeSessionId);
let compatibles = [];
let metodoAsociacion = '';
let motivoAsociacion = '';
const estadosNoAsignables = new Set(['confirmado','cancelando_expirada','expirado_sin_pago','cancelado']);
const ORIGENES_TOLERANTES = new Set(['activa_por_correo','activa_por_nombre','historico_por_correo']);
const MOTIVOS_TOLERANTES = {
  activa_por_correo: 'PAGO_STRIPE_ASOCIADO_POR_CORREO',
  activa_por_nombre: 'PAGO_STRIPE_ASOCIADO_POR_NOMBRE',
  historico_por_correo: 'PAGO_STRIPE_TARDIO_RECUPERADO_POR_CORREO',
};
const esPagoTardioRecuperable = fila => ['activo_tardio','historico_exacto','historico_tardio','historico_por_correo'].includes(String(fila?.origen_asociacion_stripe ?? ''));
const esAsociacionTolerante = fila => ORIGENES_TOLERANTES.has(String(fila?.origen_asociacion_stripe ?? ''));
const candidatosSql = (() => {
  const lista = $input.first().json?.candidatos_asociacion_stripe;
  if (!Array.isArray(lista)) return [];
  return lista
    .filter(f => f && typeof f === 'object' && f.id)
    .map(f => ({ id: f.id, nombre: f.nombre, email: f.email, sucursal: f.sucursal,
      estado_reserva: f.estado_reserva ?? null, pabau_reservado: f.pabau_reservado ?? null,
      pabau_citas_agua_ids: f.pabau_citas_agua_ids ?? [], pabau_citas_masaje_ids: f.pabau_citas_masaje_ids ?? [],
      criterio: String(f.origen_asociacion_stripe ?? 'candidata') }));
})();
// La referencia del cliente viaja en el link fijo (client_reference_id) y puede ser el
// id del borrador o el subscriber de ManyChat.
const referenciaCliente = String(pago.referencia_cliente ?? '').trim();
const referenciaCoincide = f => Boolean(referenciaCliente) && (String(f.id) === referenciaCliente || String(f.subscriber_id) === referenciaCliente);
const draftMetadataEsReferencia = Boolean(referenciaCliente && draftMetadata && draftMetadata === referenciaCliente);
function validarId(f) {
  const coincideReferencia = !referenciaCliente || String(f.id) === referenciaCliente || String(f.subscriber_id) === referenciaCliente;
  const coincideDraft = !draftMetadata || String(f.id) === draftMetadata || (draftMetadataEsReferencia && String(f.subscriber_id) === draftMetadata);
  const coincideSubscriber = !subscriberMetadata || String(f.subscriber_id) === subscriberMetadata;
  return coincideReferencia && coincideDraft && coincideSubscriber;
}
if (vinculadasAStripe.length) {
  if (vinculadasAStripe.some(f=>!validarId(f))) throw new Error('La sesiÃ³n Stripe y sus identificadores seÃ±alan reservas distintas.');
  compatibles = vinculadasAStripe;
  metodoAsociacion = 'sesion_stripe';
} else {
  compatibles = candidatasUnicas.filter(f=>{
    if (!validarId(f)) return false;
    if (!esAsociacionTolerante(f) && !referenciaCoincide(f) && !draftMetadata && !subscriberMetadata && (!emailPago || String(f.email ?? f.correo ?? '').trim().toLowerCase() !== emailPago)) return false;
    const sesionPrevia = String(f.stripe_checkout_session_id ?? '').trim();
    // Una referencia explicita (id de borrador o subscriber) vale aunque el borrador tenga
    // guardada otra sesion: Stripe puede crear una sesion nueva para la misma pre-reserva.
    // La referencia del cliente tambien es una referencia explicita: vale aunque el
    // borrador tenga guardada otra sesion de Stripe.
    const referenciaExplicita = Boolean(draftMetadata || subscriberMetadata) || referenciaCoincide(f);
    if (sesionPrevia && sesionPrevia !== stripeSessionId && !esAsociacionTolerante(f) && !referenciaExplicita) return false;
    return (esPagoTardioRecuperable(f) || !estadosNoAsignables.has(String(f.estado_reserva ?? '').toLowerCase())) && !booleano(f.reserva_confirmada) && !booleano(f.pago_recibido);
  });
  metodoAsociacion = draftMetadata ? 'id_borrador' : (subscriberMetadata ? 'subscriber_id' : 'correo_exacto');
}
const candidatosPorIdentificador = [...new Map([
  ...candidatosSql,
  ...compatibles.map(f=>({id:f.id,nombre:f.nombre,email:f.email,sucursal:f.sucursal,pabau_citas_agua_ids:f.pabau_citas_agua_ids,pabau_citas_masaje_ids:f.pabau_citas_masaje_ids})),
].map(x=>[String(x.id),x])).values()];
const pagoTardioCandidato = compatibles.some(esPagoTardioRecuperable);
// El pago puede llegar por el link compartido, sin metadata y sin sesion previa: en ese caso
// se acepta el borrador que el SQL identifico por correo o por nombre.
const asociacionToleranteCandidata = compatibles.some(esAsociacionTolerante);
const referenciaClienteCandidata = compatibles.some(referenciaCoincide);
if (!draftMetadata && !vinculadasAStripe.length && !pagoTardioCandidato && !asociacionToleranteCandidata && !referenciaClienteCandidata) {
  motivoAsociacion='PAGO_SIN_REFERENCIA_EXACTA_DE_BORRADOR';
  compatibles=[];
}
if (asociacionToleranteCandidata && compatibles.length === 1 && !pagoTardioCandidato) {
  motivoAsociacion = MOTIVOS_TOLERANTES[String(compatibles[0]?.origen_asociacion_stripe ?? '')] || 'PAGO_STRIPE_ASOCIADO_POR_COINCIDENCIA';
}
if (referenciaClienteCandidata && !motivoAsociacion) motivoAsociacion = 'PAGO_STRIPE_ASOCIADO_POR_REFERENCIA_DE_CLIENTE';
if (referenciaClienteCandidata && !draftMetadata && !subscriberMetadata) metodoAsociacion = 'referencia_cliente';
if (compatibles.length > 1) {
  motivoAsociacion = 'PAGO_STRIPE_VARIAS_RESERVAS_COMPATIBLES';
  compatibles = [];
}
if (!compatibles.length && !motivoAsociacion) motivoAsociacion = 'PAGO_STRIPE_SIN_IDENTIFICADOR_COINCIDENTE';
const d = compatibles[0] ?? {};
const pagoTardioRecuperable = esPagoTardioRecuperable(d);
const recuperacionHistorica = pagoTardioRecuperable && String(d.origen_asociacion_stripe).startsWith('historico_');
const emailBorrador = String(d.email ?? d.correo ?? '').trim().toLowerCase();
// Un vÃ­nculo explÃ­cito es vÃ¡lido aunque el pagador use otro correo.
const correoPagoDiferente = Boolean(emailBorrador && emailPago && emailBorrador !== emailPago);

const servicioAguaId = d.servicio_agua_id ?? d.service_agua_id ?? null;
const servicioTerapeutaId = d.servicio_terapeuta_id ?? d.service_terapeuta_id ?? null;
const servicioNormalizado = String(d.servicio ?? d.nombre_servicio ?? '').trim().toLowerCase().replace(/\s+/g, '_');
const premiumSoloMasaje = /^premium_day_spa(?:_facial)?_(individual|pareja|tribu)$/.test(servicioNormalizado);
const requiereAgua = premiumSoloMasaje ? false : booleano(d.requiere_agua, Boolean(servicioAguaId));
const requiereTerapeuta = premiumSoloMasaje ? true : booleano(d.requiere_terapeuta, Boolean(servicioTerapeutaId));

const terapeutas = idsUnicos([
  ...lista(d.terapeutas_asignados),
  ...lista(d.terapeutas),
  ...lista(d.terapeutas_ids)
]);
for (let i = 1; i <= 18; i += 1) {
  if (d['terapeuta_' + i]) terapeutas.push(String(idDe(d['terapeuta_' + i])));
}
const terapeutasUnicos = [...new Set(terapeutas.filter(Boolean))];
const recursosAgua = idsUnicos([
  ...lista(d.recursos_agua_asignados),
  ...lista(d.recurso_agua_asignado),
  ...lista(d['Recursos agua'])
]);
const personas = enteroPositivo(d.numero_personas ?? d.personas);
const terapeutasNecesarios = requiereTerapeuta
  ? (enteroPositivo(d.terapeutas_necesarios) || terapeutasUnicos.length || personas || 1)
  : 0;
const jacuzzisNecesarios = requiereAgua
  ? (enteroPositivo(d.jacuzzis_necesarios) || (String(d.sucursal) === '24079' && Number(personas || 1) >= 13 ? 2 : 1))
  : 0;

const faltantes = [];
if (!compatibles.length) faltantes.push('reserva_draft');
if (compatibles.length) {
  if (!String(d.nombre ?? d.nombre_completo ?? '').trim()) faltantes.push('nombre');
  if (!String(d.email ?? d.correo ?? pago.email_pago ?? '').trim()) faltantes.push('email');
  if (!String(d.phone ?? d.telefono ?? d.celular ?? '').trim()) faltantes.push('telefono');
  if (!String(d.servicio ?? d.nombre_servicio ?? '').trim()) faltantes.push('servicio');
  if (!String(d.sucursal ?? '').trim()) faltantes.push('sucursal');
  if (!d.contact_id && !d.contacto_id) faltantes.push('contact_id');
  if (!requiereAgua && !requiereTerapeuta) faltantes.push('componente_reservable');

  if (requiereAgua) {
    if (!String(d.jacuzzi_inicio ?? '').trim()) faltantes.push('jacuzzi_inicio');
    if (!servicioAguaId) faltantes.push('servicio_agua_id');
    if (recursosAgua.length < jacuzzisNecesarios) faltantes.push('recursos_agua_asignados');
  }

  if (requiereTerapeuta) {
    if (!String(d.masaje_inicio ?? '').trim()) faltantes.push('masaje_inicio');
    if (!servicioTerapeutaId) faltantes.push('servicio_terapeuta_id');
    if (!Number.isInteger(terapeutasNecesarios) || terapeutasNecesarios < 1) {
      faltantes.push('terapeutas_necesarios');
    }
    if (terapeutasUnicos.length < Math.max(1, terapeutasNecesarios || 1)) {
      faltantes.push('terapeutas_asignados');
    }
  }

  if (String(d.disponible ?? 'false').toLowerCase() !== 'true') faltantes.push('disponible');
  if (booleano(d.horario_pendiente)) faltantes.push('horario_confirmado');
}

const montoCentavos = Number(pago.monto_total);
const montoPagado = Number.isFinite(montoCentavos) && montoCentavos > 0
  ? Math.round(montoCentavos) / 100
  : null;
const monedaPago = String(pago.moneda || 'mxn').trim().toUpperCase();

const estado = String(d.estado_reserva ?? '').toLowerCase();
const retencionEnCreacion = estado === 'creando_retencion';
const pabauReservado = booleano(d.pabau_reservado);
const retencionPabauExistente = pabauReservado && ['pendiente_pago', 'requiere_revision_pago', 'requiere_revision'].includes(estado);
const pagoYaRegistrado = booleano(d.pago_recibido);
const mismaSesionStripe = Boolean(
  stripeSessionId &&
  String(d.stripe_checkout_session_id ?? '').trim() === stripeSessionId
);
const borradorConfirmadoPendienteFinalizacion =
  estado === 'confirmado' &&
  pagoYaRegistrado &&
  mismaSesionStripe;
const procesandoDesdeMs = Date.parse(String(d.procesando_desde ?? ''));
const antiguedadProcesoMs = Number.isFinite(procesandoDesdeMs) ? Date.now() - procesandoDesdeMs : Infinity;
const RECUPERACION_PROCESO_MS = 30 * 60 * 1000;
const mismaSesionParaRecuperar = mismaSesionStripe || !String(d.stripe_checkout_session_id ?? '').trim();
const recuperarReservaEnProceso = estado === 'procesando_pabau' && pabauReservado && mismaSesionParaRecuperar && antiguedadProcesoMs > RECUPERACION_PROCESO_MS;
const yaProcesada = [
  'procesando_pabau',
  'confirmado',
  'cancelando_expirada',
  'expirado_sin_pago'
].includes(estado);

return [{
  json: {
    ...d,
    requiere_agua: requiereAgua,
    requiere_terapeuta: requiereTerapeuta,
    tipo_servicio: requiereAgua && requiereTerapeuta ? 'COMPUESTO' : (requiereAgua ? 'AGUA' : 'DIRECTO'),
    servicio_agua_id: requiereAgua ? servicioAguaId : null,
    servicio_terapeuta_id: requiereTerapeuta ? servicioTerapeutaId : null,
    terapeutas_necesarios: terapeutasNecesarios,
    jacuzzis_necesarios: jacuzzisNecesarios,
    pago_confirmado: true,
    borrador_encontrado: compatibles.length === 1 && Boolean(d.id),
    metodo_asociacion: (pagoTardioRecuperable || esAsociacionTolerante(d)) ? String(d.origen_asociacion_stripe) : metodoAsociacion,
    motivo_asociacion: pagoTardioRecuperable ? 'PAGO_STRIPE_TARDIO_RECUPERABLE' : (MOTIVOS_TOLERANTES[String(d.origen_asociacion_stripe ?? '')] || motivoAsociacion),
    origen_asociacion_stripe: d.origen_asociacion_stripe || '',
    pago_stripe_tardio: pagoTardioRecuperable,
    recuperacion_historica: recuperacionHistorica,
    candidatos_por_identificador: candidatosPorIdentificador,
    correo_pago_diferente: correoPagoDiferente,
    stripe_session_previa: d.stripe_checkout_session_id ?? null,
    monto_pagado: montoPagado,
    moneda_pago: monedaPago,
    email_pago: pago.email_pago,
    stripe_checkout_session_id: pago.stripe_checkout_session_id,
    stripe_payment_intent_id: pago.stripe_payment_intent_id,
    evento_stripe_id: pago.evento_stripe_id,
    verificacion_datos: intento,
    max_verificaciones: 96,
    faltantes_para_agendar: [...new Set(faltantes)],
    datos_completos_para_agendar: faltantes.length === 0 && !yaProcesada && !retencionEnCreacion,
    borrador_confirmado_pendiente_finalizacion: borradorConfirmadoPendienteFinalizacion,
    reserva_en_proceso_o_confirmada: yaProcesada && !recuperarReservaEnProceso,
    recuperar_reserva_en_proceso: recuperarReservaEnProceso,
    retencion_pabau_existente: retencionPabauExistente || recuperarReservaEnProceso,
    retencion_en_creacion: retencionEnCreacion
  }
}];

const d = $input.first().json || {};
const detalle = JSON.stringify(d);
const esDuplicado = /23505|reservas_draft_stripe_session_uidx|duplicate key value/i.test(detalle);

if (!esDuplicado) {
  const mensaje = d.error?.message ?? d.errorMessage ?? d.message ?? detalle;
  throw new Error('Error distinto al conflicto de sesion Stripe: ' + mensaje);
}

return [{
  json: {
    conflicto_controlado: true,
    reconsultar_por_sesion_stripe: true,
    stripe_checkout_session_id: $('Analizar pago Stripe1').first().json.stripe_checkout_session_id,
    motivo: 'Otra ejecucion enlazo la sesion. Se vuelve a consultar la fila propietaria.'
  }
}];

const d = $input.first().json ?? {};

function texto(valor) {
  return String(valor ?? '').trim();
}

function normalizar(valor) {
  return texto(valor)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[_-]+/g, ' ')
    .replace(/\s+/g, ' ')
    .toLowerCase();
}

function booleano(valor, porDefecto = false) {
  if (valor === undefined || valor === null || valor === '') return porDefecto;
  if (typeof valor === 'boolean') return valor;
  return ['1', 'true', 'si', 'sÃ­', 'yes', 'paid', 'confirmado'].includes(normalizar(valor));
}

function primeraFechaHora(...valores) {
  for (const valor of valores) {
    const limpio = texto(valor);
    if (limpio) return limpio;
  }
  return '';
}

function componentesFechaHora(valor) {
  const match = texto(valor).match(/^(\d{4})-(\d{2})-(\d{2})(?:[T\s](\d{1,2}):(\d{2}))?/);
  if (!match) return { fecha: texto(valor), hora: '' };

  const anio = Number(match[1]);
  const mes = Number(match[2]);
  const dia = Number(match[3]);
  const dias = ['domingo', 'lunes', 'martes', 'miÃ©rcoles', 'jueves', 'viernes', 'sÃ¡bado'];
  const meses = [
    'enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio',
    'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre',
  ];
  const diaSemana = dias[new Date(Date.UTC(anio, mes - 1, dia)).getUTCDay()];

  let hora = '';
  if (match[4] !== undefined) {
    const hh24 = Number(match[4]);
    const mm = match[5];
    const periodo = hh24 >= 12 ? 'p. m.' : 'a. m.';
    const hh12 = hh24 % 12 || 12;
    hora = `${hh12}:${mm} ${periodo}`;
  }

  return {
    fecha: `${diaSemana} ${dia} de ${meses[mes - 1]} de ${anio}`,
    hora,
  };
}

function agregarLinea(lineas, etiqueta, valor) {
  const limpio = texto(valor);
  if (limpio) lineas.push(`${etiqueta}: ${limpio}`);
}

