function actualizarNotaPago(previa, nota, sesion) {
  if (typeof previa !== 'string') throw new Error('No se pudo leer la nota actual de Pabau; no se sobrescribirÃ¡ con texto vacÃ­o');
  const pendiente = /Pre[\s-]*reserva\s+pendiente\s+de\s+pago\.?(?:\s*El\s+abono\s+se\s+a(?:Ã±|n)adir[aÃ¡]\s+al\s+validar\s+el\s+pago\s+de\s+Stripe\.?)?/gi;
  const anuncio = /El\s+abono\s+se\s+a(?:Ã±|n)adir[aÃ¡]\s+al\s+validar\s+el\s+pago\s+de\s+Stripe\.?/gi;
  const bloque = /(?:Pago confirmado:\s*abono de|Abono recibido:)\s*\$[^\r\n]*?\bPago validado por Stripe;\s*sesi[oÃ³]n\s+([^\s.]+)\./gi;
  let encontrada = false;
  // Only replace our own pending/payment text; keep all other notes and payments.
  let texto = previa.replace(bloque, (original, id) => {
    if (id !== sesion) return original;
    if (encontrada) return '';
    encontrada = true;
    return nota;
  });
  texto = texto.replace(pendiente, () => {
    if (encontrada) return '';
    encontrada = true;
    return nota;
  }).replace(anuncio, '').trim();
  return encontrada ? texto : [texto, nota].filter(Boolean).join('\n');
}

